package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import org.eclipse.rdf4j.common.annotation.InternalUseOnly;
import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.helpers.QueryAlgebraBindingAnalysis;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;

/** Preparation-time admission for evaluating an OPTIONAL condition before opening its right input. */
@InternalUseOnly
public final class OptionalConditionEvaluation {

	private OptionalConditionEvaluation() {
	}

	public static boolean canPrefilter(LeftJoin join) {
		// Prefiltering changes condition frequency and may skip the entire RHS. Placement volatility metadata alone
		// cannot authorize either change: both the condition and skipped evaluation need the audited effect proof.
		if (!join.hasCondition() || !AlgebraEvaluationSafety.isRepeatable(join.getCondition())
				|| !AlgebraEvaluationSafety.isRepeatable(join.getRightArg())) {
			return false;
		}
		return usesLeftFrame(join);
	}

	public static boolean usesLeftFrame(LeftJoin join) {
		return QueryAlgebraBindingAnalysis.withBindingValues(join, EmptyBindingSet.getInstance())
				.leftJoinConditionUsesLeftFrame(join);
	}
}
